{
  "table": {
    "name": "molecule",
    "purpose": "One row per molecule (identified by a TRxxx code). Atoms and bonds in the atom/bond tables link back to this table. The second column is a binary sign/charge flag whose exact meaning is unresolved."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "molecule_id",
      "description": "Primary key; unique molecule identifier of the form TRxxx (e.g. TR000, TR477). Referenced by atom.col_002 and bond.col_002, so each atom and bond row belongs to one molecule.",
      "status": "resolved"
    },
    "col_002": {
      "role": "code",
      "name": "",
      "description": "Binary flag taking only values '+' (152 rows) and '-' (191 rows). Could denote net charge/sign of the molecule, or some other two-class attribute (e.g. active/inactive, cis/trans). No evidence distinguishes these readings.",
      "status": "unresolved"
    }
  }
}
